-- ============================================================
-- GENERATED FILE -- do not hand-edit.
-- Produced by apps/moba/gen_store.py from apps/moba/maps/*/store_config.yaml.
-- Owns the shopkeeper creatures (creature_template + creature_template_model),
-- their spawns (creature), and the item catalog (mod_moba_store_*).
-- ONE shopkeeper per team per map; TabId below is a tab in the addon
-- panel, not an NPC. Browsing is client-side (Catalog.lua); these tables
-- exist so the server can validate a purchase from a node id alone.
-- Team is carried in mod_moba_store_npc, NOT in faction: CFBG puts players
-- of either faction on either BG team, so faction cannot express team.
-- Shopkeepers are faction 35 (friendly to all) and immune; npc_moba_store
-- refuses players whose BG team does not match.
-- ============================================================

USE acore_world;

DELETE FROM `creature_template` WHERE `entry` BETWEEN 900300 AND 900399;
 `speed_walk`, `speed_run`, `rank`, `unit_class`, `unit_flags`,
 `type`, `type_flags`, `MovementType`, `HealthModifier`, `ArmorModifier`,
 `RegenHealth`, `flags_extra`, `ScriptName`, `VerifiedBuild`)
VALUES
(900302, 'Dkeka', 'Goods & Gear', 80, 80, 35, 1, 1.0, 1.14286, 0, 1, 770, 7, 0, 0, 1, 1, 1, 0, 'npc_moba_store', 0),
(900303, 'Tojakk', 'Goods & Gear', 80, 80, 35, 1, 1.0, 1.14286, 0, 1, 770, 7, 0, 0, 1, 1, 1, 0, 'npc_moba_store', 0);

DELETE FROM `creature_template_model` WHERE `CreatureID` BETWEEN 900300 AND 900399;

DELETE FROM `creature` WHERE `guid` BETWEEN 900300 AND 900399;
 `position_x`, `position_y`, `position_z`, `orientation`,
 `spawntimesecs`, `wander_distance`, `MovementType`)
VALUES
(900302, 900302, 900, 1, 1, 0, -193.75, 7.83, 3.0, 4.3253, 300, 0, 0),
(900303, 900303, 900, 1, 1, 0, 193.75, 7.83, 3.0, 5.0995, 300, 0, 0);

DROP TABLE IF EXISTS `mod_moba_store_npc`;
CREATE TABLE `mod_moba_store_npc` (
    `CreatureEntry` INT UNSIGNED NOT NULL PRIMARY KEY,
    `Map`           INT UNSIGNED NOT NULL,
    `Team`          TINYINT UNSIGNED NOT NULL   -- 0 = Alliance, 1 = Horde
);


DROP TABLE IF EXISTS `mod_moba_store_menu`;
CREATE TABLE `mod_moba_store_menu` (
    `Map`        INT UNSIGNED NOT NULL,
    `TabId`      INT UNSIGNED NOT NULL,
    `NodeId`     INT UNSIGNED NOT NULL,
    `ParentId`   INT UNSIGNED NOT NULL DEFAULT 0,  -- 0 = top level
    `SortOrder`  INT UNSIGNED NOT NULL DEFAULT 0,
    `Label`      VARCHAR(100) NOT NULL,
    `IsPurchase` TINYINT UNSIGNED NOT NULL DEFAULT 0,
    `CostCopper` INT UNSIGNED NOT NULL DEFAULT 0,
    PRIMARY KEY (`Map`, `TabId`, `NodeId`)
);


DROP TABLE IF EXISTS `mod_moba_store_grant`;
CREATE TABLE `mod_moba_store_grant` (
    `Map`       INT UNSIGNED NOT NULL,
    `TabId`     INT UNSIGNED NOT NULL,
    `NodeId`    INT UNSIGNED NOT NULL,
    `ItemEntry` INT UNSIGNED NOT NULL,
    -- ItemRandomSuffix.dbc id, stored positive; 0 = no suffix. The engine
    -- wants it NEGATED as randomPropertyId (see Item::GenerateItemRandomPropertyId).
    `SuffixId`  INT UNSIGNED NOT NULL DEFAULT 0,
    `Count`     INT UNSIGNED NOT NULL DEFAULT 1,
    KEY `idx_node` (`Map`, `TabId`, `NodeId`)
);


DROP TABLE IF EXISTS `mod_moba_store_sell`;
CREATE TABLE `mod_moba_store_sell` (
    `Map`       INT UNSIGNED NOT NULL,
    `ItemEntry` INT UNSIGNED NOT NULL,
    -- PER UNIT, as item_template.SellPrice is: the sell handler multiplies
    -- by the stack size it destroys. An entry absent from this table was
    -- never sold here, and cannot be sold back.
    `Copper`    INT UNSIGNED NOT NULL DEFAULT 0,
    PRIMARY KEY (`Map`, `ItemEntry`)
);


-- The hash of each map's block in client/addons/MobaHUD/Catalog.lua. Sent to
-- the addon at the handshake; on a mismatch the panel refuses to draw rather
-- than showing prices this server will not charge. A map with no row here
-- skips the check, so an older addon is not locked out by a missing table.
DROP TABLE IF EXISTS `mod_moba_store_version`;
CREATE TABLE `mod_moba_store_version` (
    `Map`  INT UNSIGNED NOT NULL PRIMARY KEY,
    `Hash` VARCHAR(16) NOT NULL
);


-- ============================================================
-- Custom item copies: entry = source entry + 900000.
-- mod_moba_item_copy is SHARED with gen_player_drops.py -- both write into
-- 900000-999999, and a source item claimed by both resolves to ONE row.
-- Hence CREATE ... IF NOT EXISTS and a per-owner DELETE; this table is
-- never dropped. The updater re-applies only files whose hash changed, so
-- a generator that clears the other's rows may not see them rebuilt.
-- ============================================================
CREATE TABLE IF NOT EXISTS `mod_moba_item_copy` (
    `Entry` INT UNSIGNED NOT NULL,
    `Owner` VARCHAR(32) NOT NULL,
    PRIMARY KEY (`Entry`, `Owner`)
);

-- Reclaim this generator's previous copies, sparing any a second owner
-- still claims.
DELETE it FROM `item_template` it
    JOIN `mod_moba_item_copy` mine ON mine.`Entry` = it.`entry` AND mine.`Owner` = 'store'
    LEFT JOIN `mod_moba_item_copy` other ON other.`Entry` = it.`entry` AND other.`Owner` <> 'store'
WHERE other.`Entry` IS NULL;

DELETE FROM `mod_moba_item_copy` WHERE `Owner` = 'store';

-- Cloned through a temporary table rather than a column list: CREATE ... LIKE
-- carries whatever schema the server actually has, so an upstream column add
-- flows through untouched. DBUpdater::ApplyFile invokes the mysql CLI once per
-- file, so one session spans these statements and the TEMPORARY table lives.
DROP TEMPORARY TABLE IF EXISTS `_moba_item_copy`;
CREATE TEMPORARY TABLE `_moba_item_copy` LIKE `item_template`;


